-- 231 (17/11/2026, lô 55): « DALF C1 · Đề 2 », phần ĐỌC viết lại khó hơn (văn bản dài hơn, câu hỏi về hàm ý).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap C1 --de 2. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo18mv42i4db051
update public.exercises set consigne = '<p><strong>Compréhension des écrits.</strong> Lisez le texte puis répondez aux questions.</p>' where id = 'lo18mv42i4db051';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Comment les auteurs définissent-ils une « information toxique » ?', '{"options":["par l''identité et les intentions de celui ou celle qui la diffuse","par l''effet qu''elle produit sur ceux qui la reçoivent","par le support sur lequel elle circule"]}'::jsonb, '{"answer":1}'::jsonb, 'Định nghĩa dựa vào tác động lên người nhận: « tout contenu dégradant la capacité des destinataires à comprendre leur environnement et à agir ».'),
  (2, 'qcm', 'Pourquoi le relativisme devient-il « tentant », selon les auteurs ?', '{"options":["Il permet de défendre la liberté d''expression.","Il dispense d''un tri devenu très difficile.","Il est encouragé par les pouvoirs publics."]}'::jsonb, '{"answer":1}'::jsonb, 'Giữa cơn lũ thông tin, « il est difficile de savoir qui croire et que penser », nên « Sombrer dans un relativisme » trở nên dễ dãi.'),
  (3, 'vf', 'Pour les auteurs, la démocratie repose uniquement sur le vote et l''État de droit.', '{}'::jsonb, '{"answer":1,"justification":"celle-ci ne repose pas seulement sur le suffrage universel et sur l’État de droit"}'::jsonb, null),
  (4, 'qcm', 'Que reprochent les auteurs à l''amende infligée à X/Twitter ?', '{"options":["Son montant est absorbé comme un simple coût d''exploitation.","Elle ne s''appliquait qu''à une petite partie des pays européens concernés.","Elle a été prononcée beaucoup trop tard."]}'::jsonb, '{"answer":0}'::jsonb, 'Khoản phạt « dérisoire par rapport aux profits », « est intégré au cost of doing business et n’a donc aucun réel effet incitatif ».'),
  (5, 'qcm', 'Quel jugement les auteurs portent-ils sur le cadre européen ?', '{"options":["Trop sévère, il menace la liberté des plateformes numériques.","Correct dans son principe, il est trop mollement appliqué.","Mal conçu, il ne pourra jamais être appliqué correctement."]}'::jsonb, '{"answer":1}'::jsonb, '« ne pèche donc pas tant par son architecture, certes perfectible, que par la timidité de sa mise en application ».'),
  (6, 'qcm', 'Le deuxième type de lutte, « l''adaptation », repose sur l''idée que…', '{"options":["le faux ne disparaîtra jamais tout à fait.","les plateformes se corrigeront d''elles-mêmes.","la régulation finira par suffire."]}'::jsonb, '{"answer":0}'::jsonb, '« un contexte dans lequel le faux et le manipulatoire ne pourront être totalement éradiqués ».'),
  (7, 'vf', 'Les auteurs proposent de priver l''infox de ses revenus publicitaires.', '{}'::jsonb, '{"answer":0,"justification":"couper son financement publicitaire, qui se chiffre en dizaines de milliards de dollars"}'::jsonb, null),
  (8, 'qcm', 'D''après Serge Tisseron, quel rapport l''infox entretient-elle avec les fragilités de ceux qui y croient ?', '{"options":["Elle s''en nourrit tout en les aggravant.","Elle n''a en réalité aucun rapport avec elles.","Elle les apaise en donnant un sentiment d''appartenance."]}'::jsonb, '{"answer":0}'::jsonb, '« l’information toxique exploite les fragilités psychologiques et sociales, qu’elle contribue à renforcer ».'),
  (9, 'qcm', 'Quelle attitude les auteurs recommandent-ils envers les « infoxiqués » ?', '{"options":["les priver d''accès aux réseaux sociaux tant qu''ils diffusent de fausses nouvelles","leur imposer des amendes dissuasives","les écouter avec bienveillance pour apaiser leur colère"]}'::jsonb, '{"answer":2}'::jsonb, '« alléger leur colère et leur frustration, les considérer avec bienveillance, prendre le temps d’aller à leur rencontre et de les entendre ».'),
  (10, 'qcm', 'Qu''est-ce que le « biais de confirmation » ?', '{"options":["l''habitude de vérifier systématiquement deux fois chaque information lue","la confiance excessive dans les sources officielles","la tendance à croire d''abord ce qui conforte nos opinions"]}'::jsonb, '{"answer":2}'::jsonb, '« nous accordons plus de foi aux informations confortant nos croyances a priori ».'),
  (11, 'qcm', 'Que reprochent les auteurs aux « faussaires informationnels » ?', '{"options":["Ils rejettent ouvertement et sans détour toute forme d''esprit critique.","Ils ignorent tout de l''éducation aux médias.","Ils se réclament de l''esprit critique tout en le pervertissant."]}'::jsonb, '{"answer":2}'::jsonb, '« les faussaires informationnels dévoient l’esprit critique, dont souvent ils se réclament ».'),
  (12, 'qcm', 'Que signifie la métaphore finale des « soldats » ?', '{"options":["Défendre le vrai exige un solide bagage de connaissances.","Les journalistes doivent bénéficier d''une protection policière renforcée.","Il faut confier la lutte contre l''infox à l''armée."]}'::jsonb, '{"answer":0}'::jsonb, 'Câu kết nối với việc « construire un socle de savoir scientifique de base au sein de la population »: những người chống thông tin độc hại « doivent être convenablement armés », tức là được trang bị kiến thức.')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42i4db051' and q.ord = v.ord;
